AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_017hGgt8Gn9DhegubZSe9XFX', arguments={'file_text': ':root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --surface-2: #f3f1ec;
  --ink: #1a1a1a;
  --ink-2: #3d3d3a;
  --muted: #5b5b58;
  --line: #e3e0d8;
  --accent: #b8553a;
  --accent-ink: #ffffff;
  --sale: #8a3a23;
  --focus: #1a1a1a;

  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20, 20, 18, 0.06);
  --shadow-md: 0 8px 24px rgba(20, 20, 18, 0.08);

  --font-sans: "Inter", "Helvetica Neue", Arial, system-ui, -apple-system, sans-serif;
  --font-display: "Fraunces", "Cormorant Garamond", Georgia, "Times New Roman", serif;

  --container: 1240px;
  --pad: clamp(16px, 4vw, 32px);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

h1, h2, h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--ink);
  margin: 0 0 .4em;
  line-height: 1.15;
}

h1 { font-size: clamp(2.2rem, 5vw, 3.6rem); }
h2 { font-size: clamp(1.6rem, 3.2vw, 2.4rem); }
h3 { font-size: 1.15rem; line-height: 1.3; }

p { margin: 0 0 .8em; }
.muted { color: var(--muted); }
.small { font-size: .875rem; }

a {
  color: inherit;
  text-decoration: none;
  border-radius: 2px;
}
a:hover { text-decoration: underline; text-underline-offset: 3px; }

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding-left: var(--pad);
  padding-right: var(--pad);
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px;
  top: -40px;
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  z-index: 1000;
  transition: top .15s ease;
}
.skip-link:focus { top: 12px; text-decoration: none; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 250, 247, 0.85);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  min-height: 68px;
}
.brand {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 500;
  letter-spacing: .01em;
}
.brand:hover { text-decoration: none; }
.brand-mark { color: var(--ink); }

.primary-nav ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 4px;
  justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  font-size: .95rem;
  color: var(--ink-2);
  border-radius: 999px;
}
.primary-nav a:hover {
  text-decoration: none;
  background: var(--surface-2);
  color: var(--ink);
}

.header-actions { display: flex; gap: 4px; align-items: center; }
.icon-btn {
  appearance: none;
  background: transparent;
  border: 1px solid transparent;
  color: var(--ink);
  width: 40px; height: 40px;
  border-radius: 10px;
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer;
  position: relative;
  transition: background .15s ease, border-color .15s ease;
}
.icon-btn:hover { background: var(--surface-2); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 10px;
  font-weight: 600;
  min-width: 16px; height: 16px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  padding: 0 4px;
}

/* Hero */
.hero {
  padding: clamp(40px, 7vw, 88px) 0 clamp(40px, 6vw, 80px);
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: clamp(24px, 5vw, 64px);
  align-items: center;
}
.eyebrow {
  font-size: .78rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
  margin: 0 0 14px;
}
.eyebrow-accent { color: var(--sale); }
.hero-lede {
  font-size: 1.1rem;
  color: var(--ink-2);
  max-width: 46ch;
  margin-top: 8px;
}
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 13px 22px;
  border-radius: 999px;
  font-size: .95rem;
  font-weight: 500;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: transform .12s ease, background .15s ease, border-color .15s ease, color .15s ease;
  text-decoration: none;
  line-height: 1;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn-primary { background: var(--ink); color: #fff; }
.btn-primary:hover { background: #2a2a2a; }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--ink); }
.btn-ghost:hover { background: var(--ink); color: #fff; }
.btn-dark { background: var(--ink); color: #fff; }
.btn-dark:hover { background: #2a2a2a; }

.hero-art {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 14px;
  aspect-ratio: 5/4;
  min-width: 0;
}
.hero-tile {
  border-radius: var(--radius);
  background-size: cover;
  background-position: center;
  box-shadow: var(--shadow-sm);
}
.tile-a {
  grid-row: 1 / 3;
  background:
    linear-gradient(135deg, rgba(0,0,0,.05), rgba(0,0,0,.18)),
    radial-gradient(ellipse at 30% 30%, #d9c7ad, #a47a55 70%);
}
.tile-b {
  background:
    linear-gradient(160deg, rgba(0,0,0,.04), rgba(0,0,0,.15)),
    radial-gradient(circle at 60% 40%, #ead9c1, #8a715a 80%);
}
.tile-c {
  background:
    linear-gradient(140deg, rgba(0,0,0,.05), rgba(0,0,0,.18)),
    radial-gradient(circle at 40% 60%, #c8d2c2, #5b6b56 90%);
}

/* Value strip */
.value-strip {
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 18px 0;
}
.value-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.value-item {
  display: flex; align-items: center; gap: 12px;
  min-width: 0;
}
.value-icon {
  width: 36px; height: 36px;
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--ink);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}
.value-title { margin: 0; font-weight: 600; font-size: .92rem; }
.value-sub { margin: 0; color: var(--muted); font-size: .82rem; }

/* Sections */
.section { padding: clamp(48px, 7vw, 88px) 0; }
.section-deals { background: var(--surface-2); }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.section-head h2 { margin: 0; }

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 500;
  color: var(--ink);
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}
.link-arrow:hover { text-decoration: none; color: var(--accent); }

/* Filters */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}
.chip {
  appearance: none;
  background: transparent;
  border: 1.5px solid var(--line);
  color: var(--ink-2);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: .9rem;
  cursor: pointer;
  transition: background .15s, color .15s, border-color .15s;
  font-family: inherit;
}
.chip:hover { border-color: var(--ink); color: var(--ink); }
.chip.is-active {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

/* Product grid */
.product-grid {
  list-style: none;
  margin: 0; padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(16px, 2.4vw, 28px);
}
.product-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  border: 1px solid var(--line);
  transition: transform .2s ease, box-shadow .2s ease;
  min-width: 0;
}
.product-card:focus-within,
.product-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--surface-2);
  background-size: cover;
  background-position: center;
}
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  background: #fff;
  color: var(--ink);
  font-size: .72rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  font-weight: 600;
}
.product-tag.new { background: var(--ink); color: #fff; }
.product-tag.sale { background: var(--sale); color: #fff; }

.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 999px;
  border: none;
  background: rgba(255,255,255,.92);
  color: var(--ink);
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: background .15s, color .15s;
}
.wishlist-btn:hover { background: #fff; color: var(--accent); }
.wishlist-btn[aria-pressed="true"] { color: var(--accent); }

.product-body {
  padding: 14px 16px 16px;
  display: flex; flex-direction: column;
  gap: 4px;
  flex: 1;
}
.product-cat {
  font-size: .75rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0;
}
.product-name {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 500;
  margin: 0 0 4px;
  letter-spacing: 0;
  line-height: 1.3;
}
.product-name a { color: var(--ink); }
.product-name a::after {
  content: "";
  position: absolute; inset: 0;
}
.product-card { position: relative; }
.product-price-row {
  margin-top: auto;
  padding-top: 10px;
  display: flex; align-items: baseline; gap: 8px;
  flex-wrap: wrap;
}
.product-price { font-weight: 600; color: var(--ink); }
.product-price-was {
  color: var(--muted);
  text-decoration: line-through;
  font-size: .9rem;
}
.product-price-save {
  font-size: .78rem;
  color: var(--sale);
  font-weight: 600;
}

/* Product image gradients (decorative placeholders that look intentional) */
.pm-1 { background-image: linear-gradient(150deg, #e8dcc5, #b39573); }
.pm-2 { background-image: linear-gradient(160deg, #d9d3c8, #6b6f60); }
.pm-3 { background-image: linear-gradient(140deg, #f1e3d3, #c89a6e); }
.pm-4 { background-image: linear-gradient(155deg, #cfd6d0, #5d6b66); }
.pm-5 { background-image: linear-gradient(135deg, #e7d6c3, #8a6a4d); }
.pm-6 { background-image: linear-gradient(165deg, #ddd5c5, #7d8474); }
.pm-7 { background-image: linear-gradient(145deg, #e3d3bb, #a47a4f); }
.pm-8 { background-image: linear-gradient(150deg, #d8d2c4, #555a4d); }

/* Deals */
.countdown {
  margin: 0;
  font-size: .92rem;
  color: var(--ink-2);
}
.countdown-time {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  background: var(--ink);
  color: #fff;
  padding: 4px 10px;
  border-radius: 6px;
  margin-left: 4px;
}

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: clamp(16px, 2.4vw, 24px);
  min-height: 520px;
}
.deal-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  border: 1px solid var(--line);
  min-width: 0;
}
.deal-feature {
  grid-row: 1 / 3;
  flex-direction: column;
}
.deal-feature .deal-media { flex: 1; min-height: 280px; }
.deal-feature .deal-body { padding: 28px; }
.deal-feature h3 {
  font-size: clamp(1.6rem, 2.6vw, 2.1rem);
  margin: 8px 0 10px;
}
.deal-media {
  background-size: cover;
  background-position: center;
  background-color: var(--surface-2);
  min-height: 160px;
}
.deal-media-a {
  background-image:
    linear-gradient(135deg, rgba(0,0,0,.1), rgba(0,0,0,.25)),
    radial-gradient(circle at 35% 35%, #efe3d0, #b89773 80%);
}
.deal-media-b {
  background-image:
    linear-gradient(140deg, rgba(0,0,0,.06), rgba(0,0,0,.2)),
    radial-gradient(circle at 60% 40%, #d8c2a8, #8b6748 90%);
}
.deal-media-c {
  background-image:
    linear-gradient(160deg, rgba(0,0,0,.1), rgba(0,0,0,.3)),
    radial-gradient(circle at 50% 35%, #f3d9a4, #6b5234 90%);
}
.deal-body {
  padding: 18px 20px 20px;
  display: flex; flex-direction: column;
  gap: 4px;
}
.badge {
  display: inline-block;
  background: var(--surface-2);
  color: var(--ink);
  font-size: .75rem;
  letter-spacing: .06em;
  text-transform: uppercase;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: 999px;
  width: fit-content;
}
.badge-sale { background: var(--sale); color: #fff; }
.deal-card .btn { margin-top: 14px; align-self: flex-start; }
.deal-card .link-arrow { margin-top: 8px; align-self: flex-start; }

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: clamp(16px, 2.4vw, 28px);
}
.editorial-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform .2s ease, box-shadow .2s ease;
  min-width: 0;
}
.editorial-card:hover, .editorial-card:focus-within {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.editorial-link { display: flex; flex-direction: column; height: 100%; color: inherit; }
.editorial-link:hover { text-decoration: none; }
.editorial-lead { grid-row: 1 / 3; }
.editorial-lead .editorial-media { aspect-ratio: 4/3.4; }
.editorial-lead h3 {
  font-size: clamp(1.4rem, 2.2vw, 1.9rem);
}
.editorial-media {
  aspect-ratio: 4/3;
  background-size: cover;
  background-position: center;
  background-color: var(--surface-2);
}
.editorial-media-1 {
  background-image:
    linear-gradient(150deg, rgba(0,0,0,.1), rgba(0,0,0,.35)),
    radial-gradient(circle at 30% 40%, #d3b790, #5e4326 90%);
}
.editorial-media-2 {
  background-image:
    linear-gradient(150deg, rgba(0,0,0,.08), rgba(0,0,0,.3)),
    radial-gradient(circle at 60% 50%, #e8d8b9, #7a6135 90%);
}
.editorial-media-3 {
  background-image:
    linear-gradient(160deg, rgba(0,0,0,.06), rgba(0,0,0,.22)),
    radial-gradient(circle at 50% 40%, #e2dfd4, #707267 90%);
}
.editorial-media-4 {
  background-image:
    linear-gradient(145deg, rgba(0,0,0,.08), rgba(0,0,0,.28)),
    radial-gradient(circle at 40% 50%, #d8c2a8, #5d4528 90%);
}
.editorial-body { padding: 18px 20px 22px; }
.kicker {
  font-size: .76rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 8px;
  font-weight: 600;
}
.editorial-card h3 { margin: 0 0 8px; }

/* Newsletter */
.newsletter {
  background: var(--ink);
  color: #f0eee7;
  padding: clamp(56px, 8vw, 96px) 0;
}
.newsletter h2 { color: #fff; }
.newsletter .eyebrow { color: #e0a48a; }
.newsletter .muted { color: #b9b6ad; }
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(24px, 5vw, 64px);
  align-items: center;
}
.newsletter-form { width: 100%; }
.field-row {
  display: flex; gap: 8px;
  background: rgba(255,255,255,.08);
  padding: 6px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.18);
  transition: border-color .15s;
}
.field-row:focus-within { border-color: #fff; }
.field-row input {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: 0;
  color: #fff;
  padding: 12px 18px;
  font: inherit;
  font-size: 1rem;
}
.field-row input::placeholder { color: rgba(255,255,255,.55); }
.field-row input:focus { outline: none; }
.field-row .btn-primary {
  background: #fff;
  color: var(--ink);
  border: none;
}
.field-row .btn-primary:hover { background: #f1ede2; }
.field-help { color: #b9b6ad; font-size: .85rem; margin: 10px 4px 0; }
.field-error {
  color: #f6b8a3;
  font-size: .9rem;
  margin: 10px 4px 0;
  font-weight: 500;
}
.field-success {
  color: #b6e0bf;
  font-size: .95rem;
  margin: 10px 4px 0;
  font-weight: 500;
}

/* Footer */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--line);
  padding: 56px 0 28px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr repeat(3, 1fr);
  gap: 32px;
  padding-bottom: 36px;
  border-bottom: 1px solid var(--line);
}
.brand-footer { color: var(--ink); }
.footer-title {
  font-family: var(--font-sans);
  font-size: .8rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 14px;
  font-weight: 600;
}
.site-footer ul {
  list-style: none; padding: 0; margin: 0;
  display: grid; gap: 8px;
}
.site-footer a { color: var(--ink-2); }
.site-footer a:hover { color: var(--ink); }
.footer-base {
  display: flex; justify-content: space-between;
  padding-top: 22px;
  flex-wrap: wrap; gap: 8px;
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-lead { grid-column: 1 / -1; grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 820px) {
  .header-inner { grid-template-columns: auto auto; }
  .primary-nav {
    grid-column: 1 / -1;
    order: 3;
    overflow-x: auto;
    margin: 0 calc(var(--pad) * -1);
    padding: 0 var(--pad) 6px;
  }
  .primary-nav ul { justify-content: flex-start; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-art { order: -1; aspect-ratio: 4/3; }
  .value-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
    min-height: 0;
  }
  .deal-feature { grid-row: auto; }
  .newsletter-inner { grid-template-columns: 1fr; }
}

@media (max-width: 560px) {
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-lead { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .field-row { flex-direction: column; border-radius: 14px; }
  .field-row .btn-primary { width: 100%; }
  .section-head { align-items: flex-start; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
  .btn:hover, .product-card:hover, .editorial-card:hover { transform: none; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .chip, .icon-btn, .field-row {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .btn-dark { background: ButtonText; color: ButtonFace; }
  :focus-visible { outline-color: Highlight; }
  .product-card, .editorial-card, .deal-card { border-color: ButtonBorder; }
}
