+  font-weight: 600;
+  padding: 5px 10px;
+  border-radius: 999px;
+  width: fit-content;
+}
+.badge-sale { background: var(--sale); color: #fff; }
+.deal-card .btn { margin-top: 14px; align-self: flex-start; }
+.deal-card .link-arrow { margin-top: 8px; align-self: flex-start; }
+
+/* Editorial */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr;
+  grid-template-rows: auto auto;
+  gap: clamp(16px, 2.4vw, 28px);
+}
+.editorial-card {
+  background: var(--surface);
+  border-radius: var(--radius);
+  overflow: hidden;
+  border: 1px solid var(--line);
+  transition: transform .2s ease, box-shadow .2s ease;
+  min-width: 0;
+}
+.editorial-card:hover, .editorial-card:focus-within {
+  transform: translateY(-2px);
+  box-shadow: var(--shadow-md);
+}
+.editorial-link { display: flex; flex-direction: column; height: 100%; color: inherit; }
+.editorial-link:hover { text-decoration: none; }
+.editorial-lead { grid-row: 1 / 3; }
+.editorial-lead .editorial-media { aspect-ratio: 4/3.4; }
+.editorial-lead h3 {
+  font-size: clamp(1.4rem, 2.2vw, 1.9rem);
+}
+.editorial-media {
+  aspect-ratio: 4/3;
+  background-size: cover;
+  background-position: center;
+  background-color: var(--surface-2);
+}
+.editorial-media-1 {
+  background-image:
+    linear-gradient(150deg, rgba(0,0,0,.1), rgba(0,0,0,.35)),
+    radial-gradient(circle at 30% 40%, #d3b790, #5e4326 90%);
+}
+.editorial-media-2 {
+  background-image:
+    linear-gradient(150deg, rgba(0,0,0,.08), rgba(0,0,0,.3)),
+    radial-gradient(circle at 60% 50%, #e8d8b9, #7a6135 90%);
+}
+.editorial-media-3 {
+  background-image:
+    linear-gradient(160deg, rgba(0,0,0,.06), rgba(0,0,0,.22)),
+    radial-gradient(circle at 50% 40%, #e2dfd4, #707267 90%);
+}
+.editorial-media-4 {
+  background-image:
+    linear-gradient(145deg, rgba(0,0,0,.08), rgba(0,0,0,.28)),
+    radial-gradient(circle at 40% 50%, #d8c2a8, #5d4528 90%);
+}
+.editorial-body { padding: 18px 20px 22px; }
+.kicker {
+  font-size: .76rem;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--muted);
+  margin: 0 0 8px;
+  font-weight: 600;
+}
+.editorial-card h3 { margin: 0 0 8px; }
+
+/* Newsletter */
+.newsletter {
+  background: var(--ink);
+  color: #f0eee7;
+  padding: clamp(56px, 8vw, 96px) 0;
+}
+.newsletter h2 { color: #fff; }
+.newsletter .eyebrow { color: #e0a48a; }
+.newsletter .muted { color: #b9b6ad; }
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: clamp(24px, 5vw, 64px);
+  align-items: center;
+}
+.newsletter-form { width: 100%; }
+.field-row {
+  display: flex; gap: 8px;
+  background: rgba(255,255,255,.08);
+  padding: 6px;
+  border-radius: 999px;
+  border: 1px solid rgba(255,255,255,.18);
+  transition: border-color .15s;
+}
+.field-row:focus-within { border-color: #fff; }
+.field-row input {
+  flex: 1;
+  min-width: 0;
+  background: transparent;
+  border: 0;
+  color: #fff;
+  padding: 12px 18px;
+  font: inherit;
+  font-size: 1rem;
+}
+.field-row input::placeholder { color: rgba(255,255,255,.55); }
+.field-row input:focus { outline: none; }
+.field-row .btn-primary {
+  background: #fff;
+  color: var(--ink);
+  border: none;
+}
+.field-row .btn-primary:hover { background: #f1ede2; }
+.field-help { color: #b9b6ad; font-size: .85rem; margin: 10px 4px 0; }
+.field-error {
+  color: #f6b8a3;
+  font-size: .9rem;
+  margin: 10px 4px 0;
+  font-weight: 500;
+}
+.field-success {
+  color: #b6e0bf;
+  font-size: .95rem;
+  margin: 10px 4px 0;
+  font-weight: 500;
+}
+
+/* Footer */
+.site-footer {
+  background: var(--surface);
+  border-top: 1px solid var(--line);
+  padding: 56px 0 28px;
+}
