+  display: grid;
+  grid-template-columns: 1.6fr repeat(3, 1fr);
+  gap: 32px;
+  padding-bottom: 36px;
+  border-bottom: 1px solid var(--line);
+}
+.brand-footer { color: var(--ink); }
+.footer-title {
+  font-family: var(--font-sans);
+  font-size: .8rem;
