+}
+
+/* Forced colors */
+@media (forced-colors: active) {
+  .btn, .chip, .icon-btn, .field-row {
+    border: 1px solid ButtonBorder;
+  }
+  .btn-primary, .btn-dark { background: ButtonText; color: ButtonFace; }
+  :focus-visible { outline-color: Highlight; }
+  .product-card, .editorial-card, .deal-card { border-color: ButtonBorder; }
+}
+
')

